<?php
/**
 * Northwind Electronics — gear that works as hard as you do - theme setup, assets and generated pages.
 *
 * @package northwind_electronics
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('northwind_electronics_setup')) {
    function northwind_electronics_setup()
    {
        load_theme_textdomain('northwind_electronics', get_template_directory() . '/languages');

        add_theme_support('title-tag');
        add_theme_support('post-thumbnails');
        add_theme_support('automatic-feed-links');
        add_theme_support('responsive-embeds');
        add_theme_support('custom-logo', array('height' => 60, 'width' => 240, 'flex-width' => true));
        add_theme_support('html5', array('search-form', 'comment-form', 'gallery', 'caption', 'style', 'script'));

        register_nav_menus(array(
            'primary' => __('Primary Menu', 'northwind_electronics'),
        ));
    }
}
add_action('after_setup_theme', 'northwind_electronics_setup');

if (!function_exists('northwind_electronics_assets')) {
    function northwind_electronics_assets()
    {
        wp_enqueue_style('northwind-electronics-style', get_stylesheet_uri(), array(), '1.0.0');
        wp_enqueue_style('northwind-electronics-builder', get_theme_file_uri('assets/css/builder.css'), array('northwind-electronics-style'), wp_get_theme()->get('Version'));
        /* Store data for the catalog, cart, COD checkout and panels. */
        wp_add_inline_script('northwind-electronics-builder', 'window.__WB_SHOP__ = Object.assign({}, window.__WB_SHOP__ || {}, {"productPath":"/product/","shopPath":"/shop/","checkoutPath":"/checkout/","confirmationPath":"/order-confirmation/","trackPath":"/track-order/","codStatuses":[{"id":"pending","label":"Not collected"},{"id":"in_transit","label":"With courier"},{"id":"collected","label":"Cash collected"},{"id":"failed","label":"Collection failed"},{"id":"waived","label":"Waived"}],"settings":{"storeName":"Northwind Electronics","tagline":"Gear that works as hard as you do","currency":"$","taxRate":5,"freeShippingOver":150,"codEnabled":true,"codFee":2.5,"codNote":"Please keep the exact amount ready - the courier cannot provide change.","currencyCode":"USD","lowStockAt":10},"api":"/?wc_shop_api=1"});', 'before');
        wp_enqueue_script('northwind-electronics-builder', get_theme_file_uri('assets/js/builder.js'), array(), wp_get_theme()->get('Version'), true);
    }
}
add_action('wp_enqueue_scripts', 'northwind_electronics_assets');


if (!function_exists('northwind_electronics_render_page')) {
    /**
     * Output the markup for one generated page.
     *
     * @param string $page_id Builder page id.
     * @param array  $pages  id => [slug, name, description].
     */
    function northwind_electronics_render_page(string $page_id, array $pages): void
    {
        if (!isset($pages[$page_id])) {
            return;
        }
        $entry = $pages[$page_id];
        $description = (string) $entry['description'];
        if ($description !== '' && !defined('WEB_CRAFT_DESCRIPTION')) {
            define('WEB_CRAFT_DESCRIPTION', $description);
        }
        echo $entry['markup'];
    }
}

