    "page-cash-on-delivery": {
        "slug": "cash-on-delivery",
        "name": "Cash on delivery",
        "description": "Everything about paying the courier in cash: fees, what to prepare and how it works.",
        "markup": "<header class=\"wb-site-header\" data-webcraft-region=\"nav\">\n  <div class=\"wb-root\">\n    <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-3b\">\n        <h1 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"brand\" data-anchor=\"brand\">\n          Northwind\n        </h1>\n        <nav class=\"wb-element wb-widget wb-widget-site-menu wb-site-menu\" id=\"wb-el-sf-3d\">\n          <ul class=\"wb-menu\">\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/index/\"  data-webcraft-page=\"page-index\"><span>Home</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/shop/\"  data-webcraft-page=\"page-shop\"><span>Shop</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/index/#featured\"  data-webcraft-anchor=\"featured\"><span>Deals</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link is-active\" href=\"/cash-on-delivery/\"  data-webcraft-page=\"page-cash-on-delivery\"><span>Cash on delivery</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/cart/\"  data-webcraft-page=\"page-cart\"><span>Cart</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/wishlist/\"  data-webcraft-page=\"page-wishlist\"><span>Wishlist</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/about/\"  data-webcraft-page=\"page-about\"><span>About</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/contact/\"  data-webcraft-page=\"page-contact\"><span>Contact</span></a></li>\n  </ul>\n        </nav>\n        <div class=\"wb-element wb-widget wb-widget-html wb-html\" id=\"wb-el-sf-3e\">\n          <span class=\"wb-cart-bar\" style=\"display:inline-flex;align-items:center;gap:6px;border:1px solid #e2e8f0;border-radius:999px;padding:7px 14px;font-size:13px;font-weight:600;text-decoration:none;color:#0f172a\">Cart <span data-wb-cart-count style=\"display:none;background:#4f46e5;color:#fff;border-radius:999px;padding:0 7px;font-size:11px\"></span></span>\n        </div>\n    </div>\n  </div>\n</header>\n<main class=\"wb-site-main\" data-webcraft-page=\"page-cash-on-delivery\">\n  <div class=\"wb-root\">\n    <section class=\"wb-element wb-container wb-section wb-arrange-vertical\" id=\"cod-info\" data-anchor=\"cod-info\">\n        <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"cod-info\" data-anchor=\"cod-info\">\n          Pay when it arrives\n        </h2>\n        <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-21\">\n          Cash on delivery means you do not pay anything online. The courier brings the parcel, you pay them, and they hand it over. There is a small handling fee, shown clearly before you confirm.\n        </div>\n        <div class=\"wb-element wb-widget wb-widget-shop-section wb-shop-section\" id=\"wb-el-sf-22\" data-wb-shop=\"cod-form\">\n          <!--webcraft:shop:cod-form-->\n        </div>\n    </section>\n    <section class=\"wb-element wb-container wb-section wb-arrange-vertical\" id=\"cod-fields\" data-anchor=\"cod-fields\">\n        <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"cod-fields\" data-anchor=\"cod-fields\">\n          The form, field by field\n        </h2>\n        <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-25\">\n            <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-26\">\n                <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"wb-el-sf-27\">\n                  Cash to collect\n                </h2>\n                <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-28\">\n                  The exact amount the courier must collect, including shipping, tax and the handling fee. Edit it before you order if you want.\n                </div>\n            </div>\n            <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-29\">\n                <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"wb-el-sf-2a\">\n                  Who will pay?\n                </h2>\n                <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-2b\">\n                  You, the person receiving the parcel, or someone else. If it is not you, we collect their name and phone so the courier can call.\n                </div>\n            </div>\n            <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-2c\">\n                <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"wb-el-sf-2d\">\n                  ID for verification\n                </h2>\n                <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-2e\">\n                  Optional. Some couriers ask for a national ID, passport or driving licence before handing over a cash order.\n                </div>\n            </div>\n            <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-2f\">\n                <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"wb-el-sf-2g\">\n                  Instructions for the courier\n                </h2>\n                <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-2h\">\n                  Anything the courier should know — a gate code, a buzzer, \"please call first\".\n                </div>\n            </div>\n        </div>\n    </section>\n  </div>\n</main>\n<footer class=\"wb-site-footer\" data-webcraft-region=\"footer\">\n  <div class=\"wb-root\">\n    <section class=\"wb-element wb-container wb-section wb-arrange-vertical\" id=\"wb-el-sf-3f\">\n        <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-3g\">\n            <div class=\"wb-element wb-widget wb-widget-div wb-div\" id=\"wb-el-sf-3h\">\n                <h2 class=\"wb-element wb-widget wb-widget-heading wb-heading\" id=\"wb-el-sf-3i\">\n                  Northwind Electronics\n                </h2>\n                <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-3j\">\n                  Independent gear, sold by verified sellers, delivered everywhere.\n                </div>\n            </div>\n            <nav class=\"wb-element wb-widget wb-widget-site-menu wb-site-menu\" id=\"wb-el-sf-3k\">\n              <ul class=\"wb-menu wb-menu--footer\">\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/index/\"  data-webcraft-page=\"page-index\"><span>Home</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/shop/\"  data-webcraft-page=\"page-shop\"><span>Shop</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link is-active\" href=\"/cash-on-delivery/\"  data-webcraft-page=\"page-cash-on-delivery\"><span>Cash on delivery</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/cart/\"  data-webcraft-page=\"page-cart\"><span>Cart</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/track-order/\"  data-webcraft-page=\"page-track-order\"><span>Track order</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/about/\"  data-webcraft-page=\"page-about\"><span>About</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/contact/\"  data-webcraft-page=\"page-contact\"><span>Contact</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/index/#faq\"  data-webcraft-anchor=\"faq\"><span>FAQ</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/seller/\"  data-webcraft-page=\"page-seller\"><span>Seller panel</span></a></li>\n    <li class=\"wb-menu__item\"><a class=\"wb-menu__link\" href=\"/admin/\"  data-webcraft-page=\"page-admin\"><span>Admin</span></a></li>\n  </ul>\n            </nav>\n        </div>\n        <div class=\"wb-element wb-widget wb-widget-paragraph wb-paragraph\" id=\"wb-el-sf-3l\">\n          © 2026 Northwind Electronics · Cash on delivery available · Built with WebCraft Pro\n        </div>\n    </section>\n  </div>\n</footer>"
